  "headline": "Esmolol hydrochloride is not on FDA's shortage list as of 2026-10-21; Corvale East has 19.9 days on hand and Corvale General has 27.8 days on hand",
  "headline_cites": ["D3", "D1", "D2"],
  "sentences": [
    {
      "text": "FDA's records show esmolol hydrochloride is not on the drug shortage list as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "Corvale East holds 214 vials of the 100 mg/10 mL presentation with 10.7 vials used per day, providing 19.9 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 386 vials of the same presentation with 13.9 vials used per day, providing 27.8 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "The product label identifies Medical Purchasing Solutions, LLC as the labeler and plant (FEI 3014288534) with a VAI inspection classification dated 2024-09-11.",
      "cites": ["E4", "E3"]
    },
    {
      "text": "The rule-based best option is to buy from Amneal Pharmaceuticals LLC, which is not on FDA's shortage list today, though its label names no plant we could place.",
      "cites": ["D4"]
    },
    {
      "text": "Alternate manufacturers Baxter Healthcare Company and Baxter Healthcare Corporation are also not on FDA's shortage list today, but their labels name no plant we could place.",
      "cites": ["D5", "D6"]
    }
  ]
}
